CREATE TABLE nibas.kodeliste_fylkesnummer (
    id serial4 NOT NULL,
    uuid text NULL,
    "label" text NULL,
    lang text NULL,
    codevalue text NULL,
    status text NULL,
    seoname text NULL,
    "owner" text NULL,
    CONSTRAINT kodeliste_fylkesnummer_pkey PRIMARY KEY (id)
);


